const int RED = 10;
const int YELLOW = 9;
const int GREEN = 11;// красный — основа пламени

void setup() {
  Serial.begin(115200);
  pinMode(RED, OUTPUT);
  pinMode(YELLOW, OUTPUT);
  pinMode(GREEN, OUTPUT);
  }
    void colorRED(){
      for(int level=0; level < 255; level++){
    analogWrite(RED, level);
      delay(2);   
  }
      delay(3000);
    for(int level=255; level >= 0; level--){
    analogWrite(RED, level);
      delay(1);   
    }
    }
         void colorYELLOW(int level){
